head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getTotalRow]<br/>GridView 컴포넌트에 바인딩된 DataList 의 전체 Row 갯수를 반환합니다.",
    "validation" : [
        "데이터가 로드되지 않았거나 DataList 가 바인딩되지 않은 경우 undefined 를 반환해야 합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - target1 : DataList 미바인딩 그리드. dataList 속성 없이 생성하여 데이터가 바인딩되지 않은 상태.
//              getTotalRow() → undefined 검증.
scwin.comp_init = async function () {
    // 기존 target 정리
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="DataList 가 바인딩되지 않은 그리드입니다. 데이터가 로드되지 않아 getTotalRow() 는 undefined 를 반환합니다."', '', 'label1');

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // ===== DataList 미바인딩 그리드 (target1) =====
    // dataList 속성을 설정하지 않은 그리드 → getTotalRow()=undefined 검증
    let strTarget1 = '';
    strTarget1 += '<w2:gridView ' + strNameSpace + ' id="" style="width:520px;height:120px;">';
    strTarget1 += '<w2:caption style="" id="caption1" value="DataList 미바인딩 그리드 (getTotalRow=undefined)"></w2:caption>';
    strTarget1 += '<w2:header style="" id="header1">';
    strTarget1 += '<w2:row style="" id="hrow1">';
    strTarget1 += '<w2:column width="160" style="" inputType="text" id="u_hcol1" value="이름"></w2:column>';
    strTarget1 += '<w2:column width="*" style="" inputType="text" id="u_hcol2" value="부서"></w2:column>';
    strTarget1 += '</w2:row>';
    strTarget1 += '</w2:header>';
    strTarget1 += '<w2:gBody style="" id="gBody1">';
    strTarget1 += '<w2:row style="" id="brow1">';
    strTarget1 += '<w2:column width="160" style="" inputType="text" id="u_name"></w2:column>';
    strTarget1 += '<w2:column width="*" style="" inputType="text" id="u_dept"></w2:column>';
    strTarget1 += '</w2:row>';
    strTarget1 += '</w2:gBody>';
    strTarget1 += '</w2:gridView>';
    scwin.target1 = await $p.dynamicCreate('target1', 'gridView', strTarget1, grp_comp);
}



// getTotalRow 확인 — DataList 가 바인딩되지 않아 getTotalRow() 는 undefined 반환
scwin.btn_getTotalRow_onclick = function () {
    let result = target1.getTotalRow();
    wf_body_bottom.getObj("scwin").setReturnValue("getTotalRow() : " + result + " (typeof : " + (typeof result) + ")");
}
